1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const SPHINX_BASE_POINTS = 1;
9	
10	// Variety points: a flat 1 up to and including four types, then 2 per type
11	// above four (so five types score 2, six types score 4).
12	const FLAT_VARIETY_POINTS = 1;
13	const VARIETY_POINTS_PER_TYPE_ABOVE = 2;
14	const TYPES_BEFORE_VARIETY_SCALES = 4;
15	
16	const countSphinxes = (army: Card[]): number =>
17	  army.filter((card) => card.monster === SPHINX).length;
18	
19	// A card's type is its monster; rank marks a variant (e.g. Undead Warrior
20	// (1) and (3)) and does not make it a separate type.
21	const typeOf = (card: Card): string => card.monster;
22	
23	const countDistinctTypes = (army: Card[]): number =>
24	  new Set(army.map(typeOf)).size;
25	
26	const varietyPoints = (typeCount: number): number =>
27	  typeCount > TYPES_BEFORE_VARIETY_SCALES
28	    ? VARIETY_POINTS_PER_TYPE_ABOVE * (typeCount - TYPES_BEFORE_VARIETY_SCALES)
29	    : FLAT_VARIETY_POINTS;
30	
31	export const scoreArmy = (army: Card[]): number =>
32	  countSphinxes(army) *
33	  (SPHINX_BASE_POINTS + varietyPoints(countDistinctTypes(army)));
34

