const varietyPoints = (typeCount: number): number => {
  const extraTypes = typeCount - TYPES_BEFORE_VARIETY_SCALES;
  return extraTypes > 0
    ? VARIETY_POINTS_PER_EXTRA_TYPE * extraTypes
    : FLAT_VARIETY_POINTS;
};
